# Get the full hero HTML with all children
full_hero = js("""(() => {
  const main = document.querySelector('main') || document.querySelector('section');
  if (!main) return 'no main/section';
  // Walk children
  const html = [];
  main.childNodes.forEach((node, i) => {
    if (node.nodeType === 1) {
      html.push('[' + i + '] <' + node.tagName.toLowerCase() + ' class="' + (node.className || '') + '">');
      html.push(node.textContent.trim().slice(0, 120));
      html.push('</' + node.tagName.toLowerCase() + '>');
    } else if (node.nodeType === 3 && node.textContent.trim()) {
      html.push('[' + i + '] TEXT: ' + node.textContent.trim().slice(0, 120));
    }
  });
  return html.join('\\n');
})()""")
print("MAIN CHILDREN:")
print(full_hero[:3000])

print("\n\n--- HERO-REGION HTML (first 2500 chars of body inner) ---")
body_start = js("document.body.innerHTML.slice(0, 2500)")
